table inet filter {
  chain forward {
    type filter hook forward priority 0; policy drop;
    ct state established,related accept
    iifname "eth1" ip daddr 10.10.20.10 tcp dport 443 accept   # LAN -> DMZ web
    iifname "eth1" oifname "eth0" tcp dport { 80, 443 } accept # LAN -> internet
    iifname "eth3" ip daddr 10.10.20.10 tcp dport 443 accept   # Lab -> DMZ web
    iifname "eth2" ip daddr 10.10.10.0/24 log prefix "DMZ-TO-LAN " drop
    log prefix "FW-DENY " limit rate 10/second
  }
}

